console.log('Webhook received payload:', JSON.stringify($json, null, 2));
console.log('Webhook resolvedEmail:', $json.resolvedEmail);
console.log('Webhook resolvedSubject:', $json.resolvedSubject);
console.log('Webhook resolvedMessage type:', typeof $json.resolvedMessage);
console.log('Webhook resolvedMessage length:', $json.resolvedMessage ? $json.resolvedMessage.length : 'undefined');
console.log('Webhook resolvedMessage preview:', $json.resolvedMessage ? $json.resolvedMessage.substring(0, 500) : 'undefined');

const email = $json.resolvedEmail ? String($json.resolvedEmail).trim() : null;
const subject = $json.resolvedSubject || 'Your Adventure Itinerary - Voyage Genie';
let message = $json.resolvedMessage || 'No itinerary available to send.';

console.log('After fallback message length:', message.length);
console.log('After fallback message preview:', message.substring(0, 500));

// Validate email
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!email || !emailRegex.test(email)) {
  console.log('Invalid email, using fallback:', email);
  message = 'Invalid email address provided.';
  return [{ json: { resolvedEmail: 'jtran112675@gmail.com', resolvedSubject: subject, resolvedMessage: message } }];
}

console.log('Sending email to:', email);
console.log('Final message length:', message.length);
console.log('Final message preview:', message.substring(0, 500));
return [{ json: { resolvedEmail: email, resolvedSubject: subject, resolvedMessage: message } }];

const message = $json.resolvedMessage || 'Fallback: No itinerary available to send.';
console.log('Final message to Gmail length:', message.length);
console.log('Final message to Gmail preview:', message.substring(0, 500));
